const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const morgan = require('morgan');   // Request logging
const rateLimit = require('express-rate-limit');

const app = express();

// ---------------------------------------------------------------------------
// 1️⃣  Middleware stack
// ---------------------------------------------------------------------------
// Basic security headers (Content‑Security‑Policy, X‑XSS‑Protection, etc.)
app.use(helmet());

// Enable CORS with a safe default (adjust origin as needed)
app.use(cors({
  origin: process.env.CORS_ORIGIN || '*', // change "*" to a whitelist in prod
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Body parser (required for POST/PUT JSON payloads)
app.use(express.json());

// HTTP request logger (combined format works well with most log aggregators)
app.use(morgan('combined'));

// Rate limiting – 100 requests per 15‑minute window per IP (tune as required)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ---------------------------------------------------------------------------
// 2️⃣  Routes
// ---------------------------------------------------------------------------

// Health‑check endpoint – keep it lightweight and never throw
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

