app.use((err, req, res, next) => {
  // Log the full error (could be sent to an external monitoring service)
  console.error(err);

  // Never leak internal stack traces in production
  const isProd = process.env.NODE_ENV === 'production';
  const status = err.status || 500;
  res.status(status).json({
    error: isProd ? 'Internal Server Error' : err.message,
    ...(isProd ? {} : { stack: err.stack }),
  });
});

// ---------------------------------------------------------------------------
// 5️⃣  Server start (configurable port)
// ---------------------------------------------------------------------------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});

// ---------------------------------------------------------------------------
// 6️⃣  Graceful shutdown (important for containers, PM2, etc.)
// ---------------------------------------------------------------------------
function shutdown(signal) {
  console.log(`Received ${signal}. Closing server…`);
  server.close(() => {
    console.log('HTTP server closed.');
    // If you have DB connections, close them here:
    //   db.end(() => process.exit(0));
    process.exit(0);
  });

