// ------------------------------------------------------------
// app.js – secure, production‑ready Express starter
// ------------------------------------------------------------

require('dotenv').config();               // load .env (PORT, CORS origins, etc.)
require('express-async-errors');          // auto‑forward async errors to middleware

const express   = require('express');
const helmet    = require('helmet');
const cors      = require('cors');
const rateLimit = require('express-rate-limit');
const pino      = require('pino');

const app = express();
const logger = pino({ level: process.env.LOG_LEVEL || 'info' });

/* -------------------- Middleware -------------------- */
app.disable('x-powered-by');               // hide framework version

app.use(helmet());                         // security headers
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || '*',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
}));                                        // restrict origins

// Basic rate limiting (adjust for your traffic pattern)
app.use(rateLimit({
  windowMs: 15 * 60 * 1000,   // 15 minutes
  max: 100,                  // limit each IP
  standardHeaders: true,
  legacyHeaders: false,
}));

app.use(express.json());                  // parse JSON bodies

// Request‑logging (structured)
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    logger.info({
      method: req.method,
      url: req.originalUrl,
      status: res.statusCode,
      duration,
      ip: req.ip,
    }, 'request');
  });
  next();
});

/* -------------------- Routes -------------------- */
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // In a real app you would fetch from a DB, apply RBAC, etc.
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com' },
  ]);
});

/* Example of a POST route with validation (future‑proof) */
const { body, validationResult } = require('express-validator');

app.post(
  '/users',
  [
    body('name').isString().trim().isLength({ min: 1, max: 100 }),
    body('email').isEmail().normalizeEmail(),
  ],
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Insert user into DB – omitted for brevity
    res.status(201).json({ message: 'User created' });
  }
);

/* -------------------- Error handling -------------------- */
app.use((err, req, res, next) => {
  // Log full stack for diagnostics, but never send it to the client
  logger.error({ err, url: req.originalUrl, method: req.method }, 'Unhandled error');

  const status = err.status || 500;
  const message = status === 500 ? 'Internal server error' : err.message;
  res.status(status).json({ error: message });
});

/* -------------------- Server start -------------------- */
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

module.exports = app;
```

