// ----- Middleware -------------------------------------------------
app.use(helmet());                         // security headers
app.use(cors({ origin: ['https://my-frontend.example.com'] })); // adjust as needed
app.use(express.json({ limit: '1mb' }));  // body‑size limit
app.use(morgan('combined'));               // HTTP request logging (or use logger)

