      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ]);
  } catch (err) {
    next(err); // forwarded to the error handler below
  }
});

// ----- 404 handler -------------------------------------------------
app.use((req, res) => {
  res.status(404).json({ error: 'Resource not found' });
});

// ----- Global error handler ----------------------------------------
app.use((err, req, res, next) => {
  // Log the full error (stack) on the server side only
  console.error(err);
  const status = err.status || 500;
  res.status(status).json({ error: 'Internal Server Error' });
});

// ----- Server bootstrap -------------------------------------------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
function shutdown(signal) {
  console.log(`Received ${signal} – closing server…`);
  server.close(() => {
    console.log('HTTP server closed.');
    // close DB connections etc. here
    process.exit(0);
  });
}
process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled Rejection:', reason);
  // optional: trigger graceful shutdown
});
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  // optional: trigger graceful shutdown
});

module.exports = app;
```

**What changed?**

1. **Helmet, CORS, body‑size limit, and optional request logging** – protects against a wide range of web‑based attacks and gives you visibility.  
