## 3. Centralised Error Handling

Express does not automatically catch async errors. Use a wrapper (or a library like **express‑async‑errors**) and a final error‑handling middleware that masks stack traces in production.

### Async wrapper

```js
// utils/asyncHandler.js
module.exports = fn => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};
```

Use it:

```js
const asyncHandler = require('./utils/asyncHandler');

app.get(
  '/users/:id',
  validateUserId,
  asyncHandler(async (req, res) => {
    const user = await getUserFromDb(req.params.id);
    if (!user) return res.status(404).json({ error: 'User not found' });
    res.json(user);
  })
);
```

### Global error‑handling middleware

```js
// Must be the *last* middleware added
app.use((err, req, res, next) => {
  // Log the full error for internal debugging
  console.error(err);

  // Do NOT leak stack traces or internal messages in production
  const response = {
    error: 'Internal Server Error',
  };
  if (process.env.NODE_ENV !== 'production') {
    response.message = err.message;
    response.stack = err.stack;
  }
  res.status(err.status || 500).json(response);
});
```

### Process‑level crash protection

```js
process.on('uncaughtException', err => {
  console.error('Uncaught Exception:', err);
  // Consider graceful shutdown, e.g., close DB connections, then exit
  process.exit(1);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});
```

