const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const createHttpError = require('http-errors');
const Joi = require('joi');

const app = express();

// ----- Middleware stack -----
app.use(helmet());                        // Security headers
app.use(
  cors({
    origin: process.env.CORS_ORIGIN?.split(',') || [], // e.g. "https://example.com"
    credentials: true,
  })
);
app.use(express.json({ limit: '100kb' })); // Body parsing with size limit

// Simple rate limiter – adjust as needed
const limiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 100,            // limit each IP to 100 req per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ----- Routes -----
app.get('/health', (req, res, next) => {
  try {
    res.json({ status: 'ok', timestamp: new Date().toISOString() });
  } catch (err) {
    next(err);
  }
});

const usersQuerySchema = Joi.object({
  limit: Joi.number().integer().min(1).max(100).optional(),
});

app.get('/users', (req, res, next) => {
  const { error, value } = usersQuerySchema.validate(req.query);
  if (error) return next(createHttpError(400, error.details[0].message));

  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  const result = value.limit ? users.slice(0, value.limit) : users;
  res.json(result);
});

// ----- Central error handler -----
app.use((err, _req, res, _next) => {
  const status = err.status || err.statusCode || 500;
  const payload = {
    error: {
      message: status === 500 ? 'Internal Server Error' : err.message,
      ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
    },
  };
  // You can replace console.error with a proper logger (pino, winston, etc.)
  console.error(err);
  res.status(status).json(payload);
});

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
const shutdown = () => {
  console.info('Shutting down gracefully...');
  server.close(() => {
    console.info('Closed out remaining connections.');
    process.exit(0);
  });
  // Force quit after 10 seconds
  setTimeout(() => {
    console.error('Forcefully shutting down.');
    process.exit(1);
  }, 10_000);
};

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

module.exports = app;
```

