const rateLimit = require('express-rate-limit');
const morgan = require('morgan');         // HTTP request logger
const { body, param, query, validationResult } = require('express-validator');

const app = express();

/* --------------- 2️⃣ Environment / defaults ------------------- */
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const isProd = NODE_ENV === 'production';

/* --------------- 3️⃣ Middleware stack -------------------------- */
// 3.1 Basic security headers
app.use(helmet());

// 3.2 CORS – adjust the origin list to your real clients
const corsOptions = {
  origin: (origin, callback) => {
    const whitelist = [
      'http://localhost:3000',
      // add your production front‑ends here
    ];
    if (!origin || whitelist.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
};
app.use(cors(corsOptions));

// 3.3 Rate limiting – protects against brute‑force / DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15‑minute window
  max: isProd ? 100 : 1000, // lower in prod, higher locally
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// 3.4 Body parsing (JSON) with size limit
app.use(express.json({ limit: '10kb' })); // reject huge payloads

// 3.5 Request logging (only in dev or when needed in prod)
if (!isProd) {
  app.use(morgan('dev'));
}

/* --------------- 4️⃣ Health endpoint --------------------------- */
app.get(
  '/health',
  (req, res) => {
    // No user‑input, so no validation needed here.
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
    });
  }
);

/* --------------- 5️⃣ Users endpoint (example) ----------------- */
/**
 * In a real app you would fetch users from a DB.
 * This example shows how to validate query parameters
 * and how to return proper error responses.
 */
app.get(
  '/users',
  // ---- Input validation chain (example: optional page & limit) ----
  [
    query('page')
      .optional()
      .isInt({ min: 1 })
      .toInt()
      .withMessage('page must be a positive integer'),
    query('limit')
      .optional()
      .isInt({ min: 1, max: 100 })
      .toInt()
      .withMessage('limit must be an integer between 1 and 100'),
  ],
  (req, res, next) => {
    // ---- 5‑a️⃣ Validate request -------------------------------------------------
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // Return a 400 with a safe, deterministic payload
      return res.status(400).json({ errors: errors.array() });
    }

    // ---- 5‑b️⃣ Business logic (mocked data) ------------------------------------
    const page = req.query.page || 1;
    const limit = req.query.limit || 10;

    // In a real implementation you would paginate the DB result set.
    const allUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    const start = (page - 1) * limit;
    const paginated = allUsers.slice(start, start + limit);

    res.json(paginated);
  }
);

/* --------------- 6️⃣ Centralised error handling ----------------- */
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log the error – in production you may want a structured logger (winston/pino)
  console.error(err);

  // Do not leak stack traces or internal messages in production
  const status = err.status || 500;
  const message = isProd
    ? 'An unexpected error occurred.'
    : err.message || 'Internal Server Error';

  res.status(status).json({
    error: {
      message,
      // OPTIONAL: expose validation errors or known client‑side problems
      // ...(err.details && { details: err.details })
    },
  });
});

/* --------------- 7️⃣ Server start & graceful shutdown ------------ */
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} (${NODE_ENV})`);
});

function shutdown() {
  console.log('Graceful shutdown initiated...');
  server.close(() => {
    console.log('HTTP server closed.');
    // If you have DB connections, close them here.
    process.exit(0);
  });

  // Force exit after 10 seconds if still hanging
  setTimeout(() => process.exit(1), 10_000).unref();
}
process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);

/* --------------- 8️⃣ Catch unhandled rejections/exceptions ------ */
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled Promise Rejection:', reason);
  // In production you might want to alert/monitor here.
});
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  // Clean up then exit – better than leaving the process in a corrupted state.
  process.exit(1);
});

/* --------------- 9️⃣ Export for testing -------------------------- */
module.exports = app;
```

### What changed & why it matters

| # | Change | Security benefit |
|---|--------|------------------|
| 1️⃣ | **`.env` support & configurable port** | Avoids hard‑coding values; you can keep secrets out of source. |
| 2️⃣ | **Helmet** | Sets many HTTP security headers (`Content‑Security‑Policy`, `X‑Frame‑Options`, `X‑Content-Type-Options`, etc.). |
| 3️⃣ | **CORS whitelist** | Prevents browsers from allowing any origin to call your API. |
| 4️⃣ | **Rate limiting** | Stops credential‑stuffing or simple denial‑of‑service attacks. |
| 5️⃣ | **JSON body size limit** | Mitigates request‑body‑based DoS. |
| 6️⃣ | **Morgan logger** (dev only) | Gives visibility while not flooding production logs. |
| 7️⃣ | **Validation (express‑validator)** | Guarantees that inputs meet type/format expectations before they reach business logic → stops injection attacks and ensures predictable behaviour. |
| 8️⃣ | **Central error handler** | Guarantees a single JSON format, protects stack traces in prod, and prevents the process from crashing on uncaught sync errors. |
| 9️⃣ | **Graceful shutdown** | Allows in‑flight requests to finish, useful when running behind a process manager (PM2, Docker, Kubernetes). |
| 🔟 | **Unhandled rejection / exception handlers** | Prevents the Node process from staying alive in a corrupted state – a classic “silent‑failure” security risk. |
| 1️⃣1️⃣ | **Exported `app`** unchanged – still useful for unit tests. |

---  

## 3️⃣ How to integrate the changes

1. **Add the new dependencies**  

   ```bash
   npm install helmet cors express-rate-limit morgan express-validator dotenv
   ```

   If you prefer a structured logger (highly recommended for production), swap `console.error` with `winston` or `pino` after installing it.

2. **Create a `.env`** (never commit it)  

   ```dotenv
   NODE_ENV=production
   PORT=3000
   ```

3. **Run lint / test**  

   If you have a test suite, run it to ensure the API contract still matches expectations. The added validation may cause existing client code to need minor adjustments (e.g., sending `page`/`limit` as numbers, not strings).

4. **Add CI checks**  

   - `npm audit --production` (fail on high severity)
   - Linting for unused variables (`eslint --max-warnings=0`)
   - Automated tests for the error‑handler (assert that a 500 never leaks stack traces in `NODE_ENV=production`).

