// Improved application with enhanced error handling, input validation, and security best practices

const express = require('express');
const helmet = require('helmet'); // Secure HTTP headers
const rateLimit = require('express-rate-limit'); // Basic rate limiting
const cors = require('cors'); // CORS handling
const morgan = require('morgan'); // Request logging
const { body, query, validationResult } = require('express-validator'); // Validation utilities

const app = express();

// ----------- Middleware Configuration -----------
// Security HTTP headers
app.use(helmet());

// Enable CORS – adjust origin as needed for production
app.use(cors({
  origin: process.env.CORS_ORIGIN || '*', // TODO: Restrict in production
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
}));

// Body parser with size limit to mitigate DoS attacks
app.use(express.json({ limit: '10kb' }));

// HTTP request logger (avoid logging sensitive data)
app.use(morgan('combined'));

// Basic rate limiting – 100 requests per 15 minutes per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(limiter);

// ---------- Helper Functions ----------
/**
 * Centralised error‑handling wrapper for async route handlers.
 * It forwards any error to the next() function, where the error
 * handling middleware can process it.
 */
const asyncHandler = fn => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

/**
 * Middleware to format validation errors from express‑validator.
 */
const handleValidation = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
};

// ---------- Routes ----------
app.get('/health', (req, res) => {
  // No user‑provided input – straightforward response
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Example of a route that accepts query parameters – we validate them
app.get(
  '/users',
  // Validate optional pagination query params (e.g., ?page=1&limit=10)
  [
    query('page').optional().isInt({ min: 1 }).toInt(),
    query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  ],
  handleValidation,
  asyncHandler(async (req, res) => {
    // In a real app, fetch users from a DB with proper pagination
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simple pagination logic (demo only)
    const page = req.query.page || 1;
    const limit = req.query.limit || users.length;
    const start = (page - 1) * limit;
    const paged = users.slice(start, start + limit);

    res.json(paged);
  })
);

// ---------- Centralised Error Handler ----------
app.use((err, req, res, next) => {
  // Log the error – in production use a proper logger like Winston
  console.error(err);

  // Avoid leaking stack traces in production
  const response = {
    error: err.message || 'Internal Server Error',
  };

  const status = err.status || 500;
  res.status(status).json(response);
});

// ---------- Server Startup ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

