  server.close(() => {
    console.log('✅ Closed out remaining connections');
    process.exit(0);
  });

  // Force quit after 10 seconds
  setTimeout(() => {
    console.error('❗ Forced shutdown');
    process.exit(1);
  }, 10_000);
}
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT',  () => shutdown('SIGINT'));

module.exports = app;
```

