| **Missing:**<br> • Helmet / security headers <br> • CORS policy <br> • Rate limiting <br> • Centralised error‑handling middleware <br> • 404 handler <br> • Input validation (even if only query strings) <br> • Logging (request IDs, error traces) <br> • Graceful shutdown / unhandled‑promise handling <br> • Environment‑based configuration (e.g. `process.env.PORT`) |

---

## 2️⃣ Recommendations – grouped by theme  

### A. Harden HTTP headers (Helmet)

```js
const helmet = require('helmet');
// Must be added before any route definitions
app.use(helmet());

// Optional: tighten CSP if you ever serve HTML
// app.use(
//   helmet.contentSecurityPolicy({
//     directives: {
//       defaultSrc: ["'self'"],
//       scriptSrc: ["'self'"],
//       objectSrc: ["'none'"],
//       upgradeInsecureRequests: [],
//     },
//   })
// );
```

*Why:* Helmet disables `X-Powered-By`, adds `X-Content-Type-Options`, `X-Frame-Options`, `Strict-Transport-Security`, etc. All of these mitigate click‑jacking, MIME‑sniffing, and a host of other attacks.

---

### B. Control Cross‑Origin Requests (CORS)

```js
const cors = require('cors');

// Example: only allow production front‑end origin
const allowedOrigins = [
  'https://myapp.example.com',
  // add dev URLs as needed
];

app.use(
  cors({
    origin: (origin, callback) => {
      // allow requests with no origin (e.g. mobile apps, curl)
      if (!origin) return callback(null, true);
      if (allowedOrigins.includes(origin)) return callback(null, true);
      callback(new Error('Not allowed by CORS'));
    },
    methods: ['GET', 'POST', 'PUT', 'DELETE'],
    credentials: true,
  })
);
```

*Why:* Prevents browsers from allowing any site to call your API.  

---

### C. Rate‑limit / brute‑force protection

```js
const rateLimit = require('express-rate-limit');

const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                 // max 100 requests per IP per window
  standardHeaders: true,   // Return rate limit info in the RateLimit-* headers
  legacyHeaders: false,
});

app.use('/users', apiLimiter); // apply only where it matters
```

*Why:* Thwarts credential‑stuffing and DoS attempts.

---

### D. Input validation & sanitisation

Even for GET endpoints you may accept query parameters (e.g., pagination). Use a schema library such as **Joi** or **express-validator**.

```js
const Joi = require('joi');

// Example: pagination for /users
const usersQuerySchema = Joi.object({
  page: Joi.number().integer().min(1).default(1),
  limit: Joi.number().integer().min(1).max(100).default(20),
});

app.get('/users', async (req, res, next) => {
  try {
    const { error, value: query } = usersQuerySchema.validate(req.query);
    if (error) {
      // Bad Request – do not expose internal details
      return res.status(400).json({ error: 'Invalid query parameters' });
    }

    // In a real app you’d query a DB with limit/offset derived from page/limit
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json(users);
  } catch (err) {
    next(err); // delegated to the central error handler
  }
});
```

*Why:* Guarantees that only the expected data types/values are processed, prevents injection attacks (SQL, NoSQL, etc.) and provides a clean error response.

If you ever add POST/PUT routes, put body‑parser & validation *before* the handler:

```js
app.use(express.json()); // parses JSON bodies
```

---

### E. Centralised error‑handling middleware

```js
// 1️⃣ 404 handler – placed AFTER all route definitions
app.use((req, res, next) => {
  res.status(404).json({ error: 'Not found' });
});

// 2️⃣ Error handler – must have four arguments
app.use((err, req, res, next) => {
  // Log the full error for ops, but never send stack traces to clients
  console.error(`[${new Date().toISOString()}]`, err);

  const status = err.status || 500;
  const message = status === 500 ? 'Internal server error' : err.message;

  res.status(status).json({ error: message });
});
```

*Why:* Guarantees that **all** uncaught exceptions produce a sane JSON response and that internal details aren’t leaked to the client.

---

### F. Logging & request IDs (optional but highly recommended)

```js
const morgan = require('morgan');
const { v4: uuidv4 } = require('uuid');

// Attach a unique ID to each request for traceability
app.use((req, res, next) => {
  req.id = uuidv4();
  res.setHeader('X-Request-ID', req.id);
  next();
});

morgan.token('id', (req) => req.id);
app.use(
  morgan(':id :method :url :status :response-time ms - :res[content-length]')
);
```

*Why:* Makes debugging production issues far easier and helps correlate logs across services.

---

### G. Environment‑based configuration & graceful shutdown

```js
// ---- config ----
const PORT = process.env.PORT || 3000;

// ---- start server ----
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown (SIGINT/SIGTERM)
function shutDown() {
  console.log('Received kill signal, shutting down gracefully...');
  server.close(() => {
    console.log('Closed out remaining connections');
    process.exit(0);
  });

  // Force quit after 10 sec
  setTimeout(() => {
    console.error('Could not close connections in time, forcing shutdown');
    process.exit(1);
  }, 10_000);
}
process.on('SIGTERM', shutDown);
process.on('SIGINT', shutDown);

// Catch unhandled promise rejections / uncaught exceptions
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled Rejection:', reason);
  // decide whether to shut down or keep alive
});
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});
```

*Why:* Hard‑coding `3000` makes the container less portable, and a clean shutdown prevents lost in‑flight requests. Also handling unhandled rejections prevents the process from silently entering a bad state.

---

## 3️⃣ Putting it all together – a revised `app.js`

```js
// -----------------------------------------------------------------------------
// app.js – secure & robust Express starter
// -----------------------------------------------------------------------------
require('dotenv').config();               // loads .env (if present)

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { v4: uuidv4 } = require('uuid');
const Joi = require('joi');

const app = express();

// ---------- Middleware ----------
app.use(helmet());

// CORS – whitelist production front‑end, allow dev origins as needed
const allowedOrigins = process.env.CORS_ORIGINS?.split(',') || [];
app.use(
  cors({
    origin: (origin, cb) => {
      if (!origin) return cb(null, true);
      if (allowedOrigins.includes(origin)) return cb(null, true);
      cb(new Error('Not allowed by CORS'));
    },
    credentials: true,
  })
);

// Rate limiting – can be fine‑tuned per route
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
});
app.use('/users', apiLimiter);

// Request ID + logging
app.use((req, res, next) => {
  req.id = uuidv4();
  res.setHeader('X-Request-ID', req.id);
  next();
});
morgan.token('id', (req) => req.id);
app.use(morgan(':id :method :url :status :response-time ms - :res[content-length]'));

// Body parser (useful if you later add POST/PUT)
app.use(express.json());

// ---------- Routes ----------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

const usersQuerySchema = Joi.object({
  page: Joi.number().integer().min(1).default(1),
  limit: Joi.number().integer().min(1).max(100).default(20),
});

app.get('/users', async (req, res, next) => {
  try {
    const { error, value: query } = usersQuerySchema.validate(req.query);
    if (error) {
      return res.status(400).json({ error: 'Invalid query parameters' });
    }

    // In a real‑world app you would replace the static array with a DB call.
    const staticUsers = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Example: simple pagination slice
    const start = (query.page - 1) * query.limit;
    const paged = staticUsers.slice(start, start + query.limit);

    res.json(paged);
  } catch (err) {
    next(err);
  }
});

// ---------- 404 handler ----------
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// ---------- Central error handler ----------
app.use((err, req, res, next) => {
  console.error(`[${new Date().toISOString()}] [${req.id}]`, err);
  const status = err.status || 500;
  const safeMessage = status === 500 ? 'Internal server error' : err.message;
  res.status(status).json({ error: safeMessage });
});

// ---------- Server bootstrap ----------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown
function shutDown() {
  console.log('Received shutdown signal – closing server...');
  server.close(() => {
    console.log('All connections closed. Exiting.');
    process.exit(0);
  });
  setTimeout(() => {
    console.error('Forcefully shutting down after timeout');
    process.exit(1);
  }, 10_000);
}
process.on('SIGTERM', shutDown);
process.on('SIGINT', shutDown);

// Unhandled errors handling
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled Rejection:', reason);
});
process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

module.exports = app;
```

**Key take‑aways**

| Concern | Mitigation |
|--------|------------|
| **Missing security headers** | `helmet()` |
| **Open CORS** | Whitelist origins via `cors()` |
| **DoS / brute‑force** | `express-rate-limit` |
| **No validation** | Joi (or express‑validator) schema for any incoming data |
| **Unhandled errors** | Central `error‑handler` + 404 middleware |
| **Hard‑coded port** | Use `process.env.PORT` |
| **No logging / tracing** | `morgan` + request‑ID header |
| **Process stays alive on fatal errors** | `unhandledRejection` / `uncaughtException` + graceful shutdown |
| **Potential info leakage** | Never return stack traces or raw error objects to clients |

