// ----------------------------------------------------------

// Core modules
const express = require('express');
const helmet = require('helmet');               // Secure HTTP headers
const cors = require('cors');                   // Controlled CORS
const morgan = require('morgan');               // Request logging
const rateLimit = require('express-rate-limit'); // DoS protection
const { body, param, validationResult } = require('express-validator'); // Validation

// Create the Express app
const app = express();

// ---------- 1️⃣  Middleware stack ----------
app.use(helmet());                                 // Sets many safe defaults
app.use(cors({                                   // Adjust origins for your client‑apps
  origin: process.env.ALLOWED_ORIGINS?.split(',') || '*',
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
}));
app.use(express.json({ limit: '10kb' }));         // Parse JSON payloads, limit size
app.use(morgan('combined'));                      // Structured request logs

// Rate limiter – global (adjust per‑route later if needed)
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15‑minute window
  max: 100,                // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use('/api/', apiLimiter); // Apply to all /api routes (or just '/' if you prefer)

// ---------- 2️⃣  Routes ----------
app.get('/health', (req, res) => {
  // Never expose internal error details – just a simple status.
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * Example of a route that *will* accept input in the future.
 * Even though the current implementation returns static data,
 * we showcase validation syntax for when parameters are added.
 */
app.get(
  '/users/:id?',               // Optional `id` param – illustrates validation
  param('id')
    .optional()
    .isInt({ gt: 0 })
    .withMessage('User ID must be a positive integer.'),
  (req, res, next) => {
    // Run validation and forward any errors to the error handler
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // 400 Bad Request for malformed input
      return res.status(400).json({ errors: errors.array() });
    }

    // In a real app you’d fetch from DB, apply RBAC, etc.
    // For demo, we hide the e‑mail to avoid leaking PII.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // If an ID was supplied, filter the list (still safe because we validated it)
    const result = req.params.id
      ? users.filter(u => u.id === Number(req.params.id))
      : users;

    res.json(
      // Mask email addresses – a simple privacy safeguard
      result.map(u => ({
        id: u.id,
        name: u.name,
        email: `${u.email.split('@')[0][0]}***@${u.email.split('@')[1]}`,
      }))
    );
  }
);

// ---------- 3️⃣  Global error handler ----------
app.use((err, req, res, next) => {
  // Log the full error for operators (but never expose internals to the client)
  console.error(`[${new Date().toISOString()}]`, err);

  // If headers are already sent, delegate to Express default
  if (res.headersSent) {
    return next(err);
  }

  // Differentiate operational errors from programming bugs
  const status = err.statusCode || 500;
  const message =
    status === 500
      ? 'Internal server error. Please try again later.'
      : err.message;

  res.status(status).json({ error: message });
});

// ---------- 4️⃣  Server start ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  // Use a structured log line – useful for orchestration tools
  console.log(`🚀 Server listening on http://0.0.0.0:${PORT}`);
});

module.exports = app;
```

